<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --blue:#3861FB;--navy:#0D1421;--gray:#808A9D;--green:#16c784;--red:#ea3943;
  --bg:#fff;--bg-alt:#f8f9fa;--border:#eff2f5;--text:#0D1421;--text2:#808A9D;
  --font:'Inter',system-ui,-apple-system,sans-serif;
}
html{font-size:14px;-webkit-font-smoothing:antialiased}
body{font-family:var(--font);color:var(--text);background:var(--bg);line-height:1.5}
a{color:var(--blue);text-decoration:none}
a:hover{text-decoration:underline}
button{font-family:var(--font);cursor:pointer;border:none;background:none;font-size:inherit;color:inherit}

/* NAV */
.nav{background:var(--navy);padding:0 24px;display:flex;align-items:center;height:56px;position:sticky;top:0;z-index:100}
.nav-logo{color:#fff;font-weight:700;font-size:1.14rem;display:flex;align-items:center;gap:8px;margin-right:28px;white-space:nowrap}
.nav-logo svg{width:28px;height:28px}
.nav-links{display:flex;gap:4px;flex:1}
.nav-links button{color:rgba(255,255,255,.7);padding:8px 14px;border-radius:6px;font-size:.875rem;font-weight:500;white-space:nowrap;transition:background .15s,color .15s}
.nav-links button:hover,.nav-links button.active{color:#fff;background:rgba(255,255,255,.1)}
.nav-right{display:flex;gap:8px;margin-left:16px}
.nav-right .btn-login{color:rgba(255,255,255,.85);padding:8px 16px;border-radius:6px;font-weight:500;font-size:.875rem}
.nav-right .btn-signup{background:var(--blue);color:#fff;padding:8px 16px;border-radius:6px;font-weight:600;font-size:.875rem}

/* TOP BAR METRICS */
.metrics-bar{background:var(--bg-alt);border-bottom:1px solid var(--border);padding:10px 24px;display:flex;align-items:center;gap:32px;overflow-x:auto}
.metric{display:flex;align-items:center;gap:6px;white-space:nowrap}
.metric-label{color:var(--text2);font-size:.8rem;font-weight:500}
.metric-value{font-weight:600;font-size:.875rem;font-variant-numeric:tabular-nums}
.metric-change{font-size:.75rem;font-weight:600;font-variant-numeric:tabular-nums}
.metric-change.up{color:var(--green)}
.metric-change.down{color:var(--red)}
.metric-badge{background:#fff3cd;color:#856404;font-size:.7rem;padding:2px 8px;border-radius:10px;font-weight:600}
.metric-fng{display:flex;align-items:center;gap:4px}
.fng-meter{width:60px;height:6px;border-radius:3px;background:linear-gradient(90deg,var(--red) 0%,#f0ad4e 40%,#5cb85c 70%,var(--green) 100%);position:relative}
.fng-dot{width:10px;height:10px;border-radius:50%;background:var(--navy);border:2px solid #fff;position:absolute;top:-2px;box-shadow:0 1px 3px rgba(0,0,0,.2)}

/* PROMO BANNER */
.promo-banner{padding:12px 24px;background:linear-gradient(90deg,#1a1a2e 0%,#16213e 50%,#0f3460 100%);position:relative;overflow:hidden}
.promo-slides{display:flex;transition:transform .4s ease}
.promo-slide{min-width:100%;display:flex;align-items:center;justify-content:center;gap:12px;color:#fff;font-size:.9rem;font-weight:500;padding:4px 0}
.promo-slide .promo-cta{background:var(--blue);color:#fff;padding:6px 18px;border-radius:20px;font-size:.8rem;font-weight:600;transition:background .2s}
.promo-slide .promo-cta:hover{background:#2554e6;text-decoration:none}
.promo-nav{position:absolute;top:50%;transform:translateY(-50%);background:rgba(255,255,255,.15);color:#fff;width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:1rem;transition:background .2s}
.promo-nav:hover{background:rgba(255,255,255,.3)}
.promo-nav.prev{left:12px}
.promo-nav.next{right:12px}
.promo-dots{display:flex;justify-content:center;gap:6px;margin-top:4px}
.promo-dots span{width:6px;height:6px;border-radius:50%;background:rgba(255,255,255,.3);transition:background .2s}
.promo-dots span.active{background:#fff}

/* AI ALERTS */
.ai-bar{padding:12px 24px;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.ai-bar-label{display:flex;align-items:center;gap:6px;font-weight:600;font-size:.85rem;color:var(--navy);white-space:nowrap}
.ai-bar-label svg{color:var(--blue)}
.ai-bar-prompt{background:var(--bg-alt);border:1px solid var(--border);border-radius:8px;padding:6px 12px;font-size:.8rem;color:var(--text);flex:1;min-width:200px}
.ai-bar-suggestions{display:flex;gap:6px;flex-wrap:wrap}
.ai-bar-suggestions button{background:var(--bg-alt);border:1px solid var(--border);border-radius:20px;padding:4px 12px;font-size:.75rem;color:var(--text2);font-weight:500;transition:all .15s;white-space:nowrap}
.ai-bar-suggestions button:hover{border-color:var(--blue);color:var(--blue)}

/* TABS AREA */
.tabs-area{padding:12px 24px 0;border-bottom:1px solid var(--border)}
.cat-tabs{display:flex;gap:2px;margin-bottom:12px;overflow-x:auto}
.cat-tabs button{padding:8px 16px;border-radius:8px 8px 0 0;font-size:.85rem;font-weight:500;color:var(--text2);border-bottom:2px solid transparent;transition:all .15s;white-space:nowrap}
.cat-tabs button:hover{color:var(--text)}
.cat-tabs button.active{color:var(--blue);border-bottom-color:var(--blue);font-weight:600}
.network-tabs{display:flex;gap:2px;margin-bottom:-1px;overflow-x:auto}
.network-tabs button{padding:6px 14px;border-radius:20px;font-size:.8rem;font-weight:500;color:var(--text2);border:1px solid transparent;transition:all .15s;white-space:nowrap}
.network-tabs button:hover{color:var(--text);background:var(--bg-alt)}
.network-tabs button.active{color:var(--blue);background:#eef1ff;border-color:#c7d2fe}

/* TABLE CONTROLS */
.table-controls{display:flex;align-items:center;gap:8px;padding:12px 24px;border-bottom:1px solid var(--border);flex-wrap:wrap}
.table-controls .sort-btn{padding:6px 14px;border-radius:6px;font-size:.8rem;font-weight:500;color:var(--text);background:var(--bg-alt);border:1px solid var(--border);display:flex;align-items:center;gap:4px;transition:all .15s}
.table-controls .sort-btn:hover{border-color:var(--blue);color:var(--blue)}
.table-controls .sort-btn.active{background:#eef1ff;border-color:var(--blue);color:var(--blue)}
.table-controls .sort-btn svg{width:12px;height:12px}
.table-controls .spacer{flex:1}
.ctrl-btn{padding:6px 14px;border-radius:6px;font-size:.8rem;font-weight:500;color:var(--text2);background:var(--bg-alt);border:1px solid var(--border);display:flex;align-items:center;gap:4px;transition:all .15s}
.ctrl-btn:hover{border-color:var(--gray);color:var(--text)}
.ctrl-btn svg{width:14px;height:14px}

/* DROPDOWN PANELS */
.dropdown-panel{position:absolute;top:100%;right:0;background:#fff;border:1px solid var(--border);border-radius:8px;box-shadow:0 8px 24px rgba(0,0,0,.12);padding:12px;z-index:50;min-width:200px;display:none}
.dropdown-panel.open{display:block}
.dropdown-panel label{display:flex;align-items:center;gap:8px;padding:6px 4px;font-size:.8rem;color:var(--text);cursor:pointer;border-radius:4px}
.dropdown-panel label:hover{background:var(--bg-alt)}
.dropdown-panel input[type="checkbox"]{accent-color:var(--blue)}

/* FILTER PANEL */
.filter-panel{background:var(--bg-alt);border-bottom:1px solid var(--border);padding:16px 24px;display:none}
.filter-panel.open{display:flex;gap:24px;flex-wrap:wrap;align-items:flex-start}
.filter-group{display:flex;flex-direction:column;gap:6px}
.filter-group label{font-size:.75rem;font-weight:600;color:var(--text2);text-transform:uppercase;letter-spacing:.04em}
.filter-group select,.filter-group input{padding:6px 10px;border:1px solid var(--border);border-radius:6px;font-size:.8rem;font-family:var(--font);background:#fff}
.filter-apply{padding:6px 20px;background:var(--blue);color:#fff;border-radius:6px;font-weight:600;font-size:.8rem;margin-top:auto}
.filter-apply:hover{background:#2554e6}

/* INDEX TRACKER ROW */
.index-row{display:flex;align-items:center;gap:16px;padding:10px 24px;background:linear-gradient(90deg,#f0f4ff 0%,#fff 100%);border-bottom:1px solid var(--border);font-size:.85rem}
.index-row .idx-name{font-weight:600;color:var(--navy)}
.index-row .idx-price{font-weight:600;font-variant-numeric:tabular-nums}
.index-row .idx-change{font-weight:600;font-size:.8rem;font-variant-numeric:tabular-nums}
.index-row .idx-change.up{color:var(--green)}
.index-row .idx-change.down{color:var(--red)}

/* TABLE */
.table-wrap{overflow-x:auto}
table{width:100%;border-collapse:collapse;min-width:1100px}
thead th{position:sticky;top:56px;background:var(--bg-alt);padding:10px 12px;font-size:.75rem;font-weight:600;color:var(--text2);text-transform:uppercase;letter-spacing:.03em;text-align:right;white-space:nowrap;border-bottom:1px solid var(--border);cursor:pointer;user-select:none}
thead th:first-child,thead th:nth-child(2){text-align:left}
thead th:hover{color:var(--text)}
thead th .sort-arrow{font-size:.65rem;margin-left:2px;opacity:.4}
thead th.sorted .sort-arrow{opacity:1;color:var(--blue)}
tbody tr{border-bottom:1px solid var(--border);transition:background .1s}
tbody tr:hover{background:#f8faff}
tbody td{padding:10px 12px;font-size:.85rem;white-space:nowrap;font-variant-numeric:tabular-nums;text-align:right}
tbody td:first-child{color:var(--text2);font-weight:500;text-align:center;width:50px}
tbody td:nth-child(2){text-align:left}
td.name-cell{display:flex;align-items:center;gap:8px;white-space:nowrap}
.coin-icon{width:24px;height:24px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:.65rem;font-weight:700;color:#fff;flex-shrink:0}
.coin-name{font-weight:600;color:var(--navy)}
.coin-symbol{color:var(--text2);font-size:.75rem;font-weight:500}
.pct{font-weight:600;font-size:.8rem}
.pct.up{color:var(--green)}
.pct.down{color:var(--red)}
.supply-text{color:var(--text2);font-size:.8rem}
.sparkline{width:120px;height:40px}
.sparkline svg{width:100%;height:100%}

/* PAGINATION */
.pagination{display:flex;align-items:center;justify-content:space-between;padding:16px 24px;border-top:1px solid var(--border);flex-wrap:wrap;gap:12px}
.page-info{font-size:.8rem;color:var(--text2)}
.page-buttons{display:flex;gap:4px}
.page-buttons button{width:36px;height:36px;border-radius:6px;font-size:.85rem;font-weight:500;color:var(--text2);border:1px solid var(--border);transition:all .15s}
.page-buttons button:hover{border-color:var(--blue);color:var(--blue)}
.page-buttons button.active{background:var(--blue);color:#fff;border-color:var(--blue)}
.page-buttons button.ellipsis{border:none;cursor:default;color:var(--text2)}
.page-buttons button.ellipsis:hover{color:var(--text2)}

/* MARKET SUMMARY */
.market-summary{padding:32px 24px;border-top:1px solid var(--border);max-width:900px}
.market-summary h2{font-size:1.1rem;font-weight:700;margin-bottom:12px;color:var(--navy)}
.market-summary p{font-size:.875rem;color:#444;line-height:1.7}
.market-summary .more-content{display:none;margin-top:8px}
.market-summary .more-content.open{display:block}
.market-summary .read-more{color:var(--blue);font-weight:600;font-size:.85rem;margin-top:8px;display:inline-block;cursor:pointer}
.market-summary .read-more:hover{text-decoration:underline}

/* INFO CONTENT */
.info-content{padding:32px 24px;border-top:1px solid var(--border)}
.info-content h2{font-size:1.1rem;font-weight:700;margin-bottom:8px;color:var(--navy)}
.info-content h3{font-size:.95rem;font-weight:600;margin:20px 0 6px;color:var(--navy)}
.info-content p{font-size:.875rem;color:#444;line-height:1.7}

/* FOOTER */
footer{background:var(--navy);color:rgba(255,255,255,.6);padding:40px 24px 24px;margin-top:40px}
.footer-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:32px;margin-bottom:32px}
.footer-col h4{color:#fff;font-size:.8rem;font-weight:600;text-transform:uppercase;letter-spacing:.05em;margin-bottom:12px}
.footer-col a{display:block;font-size:.8rem;color:rgba(255,255,255,.5);padding:3px 0;transition:color .15s}
.footer-col a:hover{color:#fff;text-decoration:none}
.footer-bottom{border-top:1px solid rgba(255,255,255,.1);padding-top:16px;font-size:.75rem;text-align:center}

/* RESPONSIVE */
@media(max-width:768px){
  .nav-links{display:none}
  .metrics-bar{gap:16px;padding:10px 16px}
  .ai-bar{padding:10px 16px}
  .ai-bar-suggestions{display:none}
  .tabs-area{padding:10px 16px 0}
  .table-controls{padding:10px 16px}
  .pagination{padding:12px 16px}
  .market-summary,.info-content{padding:24px 16px}
}

/* COLUMNS DROPDOWN */
.columns-wrapper{position:relative;display:inline-flex}
.filters-wrapper{position:relative;display:inline-flex}
</style>
</head>
