function genSparkline(trend, volatility) {
  const pts = [];
  let val = 50;
  for (let i = 0; i < 14; i++) {
    val += (Math.random() - 0.45 + trend * 0.12) * volatility;
    val = Math.max(5, Math.min(95, val));
    pts.push(val);
  }
  const min = Math.min(...pts), max = Math.max(...pts);
  const range = max - min || 1;
  const w = 120, h = 40, pad = 2;
  const coords = pts.map((v, i) => {
    const x = pad + (i / (pts.length - 1)) * (w - 2 * pad);
    const y = pad + (1 - (v - min) / range) * (h - 2 * pad);
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  });
  const isUp = trend >= 0;
  const color = isUp ? 'var(--green)' : 'var(--red)';
  const fillId = 'g' + Math.random().toString(36).substr(2,6);
  const lastPt = coords[coords.length - 1].split(',');
  return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">
    <defs><linearGradient id="${fillId}" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="${isUp ? '#16c784' : '#ea3943'}" stop-opacity="0.15"/>
      <stop offset="100%" stop-color="${isUp ? '#16c784' : '#ea3943'}" stop-opacity="0"/>
    </linearGradient></defs>
    <polygon points="${coords.join(' ')} ${lastPt[0]},${h} ${pad},${h}" fill="url(#${fillId})"/>
    <polyline points="${coords.join(' ')}" fill="none" stroke="${color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
  </svg>`;
}

function fmtPrice(p) {
  if (p >= 1000) return '$' + p.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2});
  if (p >= 1) return '$' + p.toFixed(2);
  if (p >= 0.01) return '$' + p.toFixed(4);
  return '$' + p.toFixed(8);
}

function fmtBig(n) {
  if (n >= 1e12) return '$' + (n/1e12).toFixed(2) + 'T';
  if (n >= 1e9) return '$' + (n/1e9).toFixed(2) + 'B';
  if (n >= 1e6) return '$' + (n/1e6).toFixed(2) + 'M';
  return '$' + n.toLocaleString();
}

function fmtSupply(n, sym) {
  if (n >= 1e12) return (n/1e12).toFixed(2) + 'T ' + sym;
  if (n >= 1e9) return (n/1e9).toFixed(2) + 'B ' + sym;
  if (n >= 1e6) return (n/1e6).toFixed(2) + 'M ' + sym;
  return n.toLocaleString() + ' ' + sym;
}

function pctClass(v) { return v >= 0 ? 'up' : 'down'; }
function pctFmt(v) { return (v >= 0 ? '+' : '') + v.toFixed(2) + '%'; }

function renderTable() {
  const tbody = document.getElementById('cryptoBody');
  tbody.innerHTML = '';
  COINS.forEach((c, i) => {
    const trend = c.h7d > 3 ? 1 : c.h7d < -1 ? -1 : 0;
    const vol = c.h7d > 5 ? 2.5 : 1.5;
    const spark = genSparkline(trend, vol);
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td>${i+1}</td>
      <td style="text-align:left"><div class="name-cell">
        <div class="coin-icon" style="background:${c.c}">${c.s.charAt(0)}</div>
        <span class="coin-name">${c.n}</span>
        <span class="coin-symbol">${c.s}</span>
      </div></td>
      <td>${fmtPrice(c.p)}</td>
      <td class="col-1h"><span class="pct ${pctClass(c.h1)}">${pctFmt(c.h1)}</span></td>
      <td class="col-24h"><span class="pct ${pctClass(c.h24)}">${pctFmt(c.h24)}</span></td>
      <td class="col-7d"><span class="pct ${pctClass(c.h7d)}">${pctFmt(c.h7d)}</span></td>
      <td class="col-mcap">${fmtBig(c.mc)}</td>
      <td class="col-vol">${fmtBig(c.v)}</td>
      <td class="col-supply"><span class="supply-text">${fmtSupply(c.sup, c.supS)}</span></td>
      <td class="col-spark"><div class="sparkline">${spark}</div></td>
    `;
    tbody.appendChild(tr);
  });
}

